// Shared first-person controls for the interior workshop and streaming city.
(function(){'use strict';
class Explorer{
 constructor(canvas,{spawn,collider,interact,onMove,onFrame,maxFrameDelta=.066,maxFPS=60}={}){
  this.canvas=canvas;this.renderer=new CastleRender.Renderer(canvas);this.renderer.ink=0;this.cam={yaw:1,pitch:.35,dist:22,tx:0,ty:4,tz:0,fov:.75};this.col=collider||new CastleWalk.Multi([]);this.walker=null;this.spawn=spawn;this.interact=interact;this.maxFrameDelta=maxFrameDelta;this.frameInterval=1000/maxFPS;this.onMove=onMove;this.onFrame=onFrame;this.frames=0;this.running=true;this.paused=false;
  let drag=null;canvas.onpointerdown=e=>{canvas.focus({preventScroll:true});if(this.walker)return;drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);};canvas.onclick=()=>{if(!this.walker)return;this.lookCaptured=!this.lookCaptured;if(!this.lookCaptured){if(document.pointerLockElement===canvas)document.exitPointerLock();return;}if(canvas.requestPointerLock)try{const pending=canvas.requestPointerLock();pending?.catch(()=>{});}catch{} };canvas.onpointerup=()=>drag=null;canvas.onpointermove=e=>{const locked=document.pointerLockElement===canvas;if(!locked&&!drag&&!this.lookCaptured)return;const dx=locked?e.movementX:this.lookCaptured?e.movementX:e.clientX-drag[0],dy=locked?e.movementY:this.lookCaptured?e.movementY:e.clientY-drag[1];if(!locked)drag=[e.clientX,e.clientY];if(this.walker){this.walker.yaw+=dx*.005;this.walker.pitch=Math.max(-1.2,Math.min(1.2,this.walker.pitch-dy*.005));}else{this.cam.yaw-=dx*.006;this.cam.pitch=Math.max(.04,Math.min(1.3,this.cam.pitch+dy*.005));}this.invalidate();};document.addEventListener('pointerlockchange',()=>{drag=null;this.lookCaptured=document.pointerLockElement===canvas;if(this.walker)this.walker.keys={};});canvas.onwheel=e=>{e.preventDefault();if(!this.walker){this.cam.dist=Math.max(12,Math.min(180,this.cam.dist*Math.exp(e.deltaY*.001)));this.invalidate();}};
  addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName))return;if(e.key.toLowerCase()==='e'&&!e.repeat){e.preventDefault();this.interact?.();}if(e.key==='Escape'){this.lookCaptured=false;if(document.pointerLockElement===canvas)document.exitPointerLock();if(this.walker)this.walker.keys={};return;}if(this.walker){this.walker.keys[e.key===' '?'space':e.key.toLowerCase()]=true;if([' ','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();}});addEventListener('keyup',e=>{if(this.walker)this.walker.keys[e.key===' '?'space':e.key.toLowerCase()]=false;});addEventListener('blur',()=>{if(this.walker)this.walker.keys={};});
  let last=performance.now();const tick=now=>{if(!this.running)return;if(document.hidden){last=now;requestAnimationFrame(tick);return;}const dt=Math.min(this.maxFrameDelta,(now-last)/1000);last=now;if(this.walker){this.onMove?.();if(!this.paused){let remaining=dt;while(remaining>1e-6){const step=Math.min(1/60,remaining);this.walker.update(step);remaining-=step;}}}this.onFrame?.();if((this.dirty||this.signature()!==this.lastSignature)&&(!this.lastDraw||now-this.lastDraw>=this.frameInterval-.5)){this.draw();this.lastDraw=now;}requestAnimationFrame(tick);};requestAnimationFrame(tick);
 }
 walk(spawn=this.spawn){this.walker=new CastleWalk.Walker(this.col,spawn);this.walker.spawn0=spawn;this.canvas.focus({preventScroll:true});}
 invalidate(){this.dirty=true;}
 signature(){const w=this.walker,c=this.cam;return [w?.x,w?.y,w?.z,w?.yaw,w?.pitch,c.yaw,c.pitch,c.dist,this.canvas.clientWidth,this.canvas.clientHeight].join('|');}
 overview(){this.lookCaptured=false;if(document.pointerLockElement===this.canvas)document.exitPointerLock();this.walker=null;this.cam.fp=null;this.canvas.focus({preventScroll:true});}
 draw(){const c=this.canvas,dpr=Math.min(1.5,devicePixelRatio||1),w=Math.round(c.clientWidth*dpr),h=Math.round(c.clientHeight*dpr);if(c.width!==w||c.height!==h){c.width=w;c.height=h;}if(this.walker){this.cam.fp=this.walker.camera();this.cam.shadowFocus={cx:this.walker.x,cz:this.walker.z,r:35,h:25};}else{this.cam.fp=null;delete this.cam.shadowFocus;}this.renderer.draw(this.cam);this.dirty=false;this.frames++;this.lastDraw=performance.now();this.lastSignature=this.signature();}
}
window.TownExplorer=Explorer;
})();
